        is_valid, error = self.validate_type(p_left_image, 'p_left_image', str)
        if not is_valid:
            return error
        
        p_right_image = params.get('p_right_image', None)
        if p_right_image is None:
            return self.handle_error(f"Required parameter 'p_right_image' is missing", 400)
        is_valid, error = self.validate_type(p_right_image, 'p_right_image', str)
        if not is_valid:
            return error
        
        p_calibration_data = params.get('p_calibration_data', None)
        if p_calibration_data is None:
            return self.handle_error(f"Required parameter 'p_calibration_data' is missing", 400)
        is_valid, error = self.validate_type(p_calibration_data, 'p_calibration_data', dict)
        if not is_valid:
            return error
        

        p_focal_length = p_calibration_data.get('p_focal_length', None)
        if p_focal_length is None:
            return self.handle_error(f"Required parameter 'p_focal_length' is missing", 400)
        is_valid, error = self.validate_type(p_focal_length, 'p_focal_length', (float, int))
        if not is_valid:
            return error
        if p_focal_length is not None:
            p_focal_length = float(p_focal_length)
        
        p_baseline = p_calibration_data.get('p_baseline', None)
        if p_baseline is None:
            return self.handle_error(f"Required parameter 'p_baseline' is missing", 400)
        is_valid, error = self.validate_type(p_baseline, 'p_baseline', (float, int))
        if not is_valid:
            return error
        if p_baseline is not None:
            p_baseline = float(p_baseline)
        
        p_time_of_capture = p_calibration_data.get('p_time_of_capture', None)
        if p_time_of_capture is not None:
            is_valid, error = self.validate_type(p_time_of_capture, 'p_time_of_capture', str)
            if not is_valid:
                return error
        
        if p_time_of_capture is not None and p_time_of_capture not in ["Morning", "Afternoon", "Evening", "Night"]:
            return self.handle_error(f"Parameter 'p_time_of_capture' not in valid enum", 400)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Robotics_vision_depth_perception",
                "p_left_image": p_left_image,
                "p_right_image": p_right_image,
                "p_calibration_data": p_calibration_data
            }
        }

